/**
 * Detects whether a string contains a number.
 *
 * @param string $input The input string to check.
 *
 * @return bool True if the string contains a number, false otherwise.
 */
function hasNumber($input) {
    // Regular expression pattern to match numbers
    $pattern = '/\d+/', // Matches one or more digits
          // $pattern = '/\D+/', // Matches one or more non-digit characters
          // $pattern = '/\D+$/'; // Matches one or more non-digit characters at the end of the string

    // Use preg_match to check if the string matches the pattern
    return preg_match($pattern, $input)!== false;
}

